"use client";

import { useState, useMemo, useEffect, useRef, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { MOCK_PRODUCTS, CATEGORY_FILTERS, filterProducts } from "@/data/store-data";
import brandLogos from "@/data/brandLogos";
import { StoreProductCard } from "@/components/ui/cards/StoreProductCard";
import { 
  ChevronDown, SlidersHorizontal, ArrowUpDown, 
  Play, Square, Info 
} from "lucide-react";
import { useSettings } from "@/context/SettingsContext";

// Reuse your existing FilterContent component or import it
// import { FilterContent } from "./CategoryClient"; 

export default function BrandClient({ brandSlug }: { brandSlug: string }) {
  // 1. DATA PREPARATION
  const brandInfo = useMemo(() => {
    return brandLogos.find(b => b.name.toLowerCase() === brandSlug.toLowerCase());
  }, [brandSlug]);

  const products = useMemo(() => {
    return MOCK_PRODUCTS.filter((p) => p.brand.toLowerCase() === brandSlug.toLowerCase());
  }, [brandSlug]);

  const maxPriceLimit = useMemo(() => {
    if (products.length === 0) return 10000;
    return Math.ceil(Math.max(...products.map((p) => p.price)) / 1000) * 1000;
  }, [products]);

  // 2. STATE & UI CONTROLS
  const [activeDrawer, setActiveDrawer] = useState<"filter" | "sort" | null>(null);
  const [sortBy, setSortBy] = useState("newest");
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);
  const scrollRef = useRef<number | null>(null);
  const { settings } = useSettings();

  const [activeFilters, setActiveFilters] = useState<Record<string, string[]>>({
    priceRange: [`0-${maxPriceLimit}`],
  });

  // 3. AUTO SCROLL ENGINE (Logic preserved from your Category page)
  const currentScrollSpeed = settings?.autoScrollLevel ?? 3;

  const stopAutoScroll = useCallback(() => {
    setIsAutoScrolling(false);
    if (scrollRef.current) cancelAnimationFrame(scrollRef.current);
  }, []);

  const toggleAutoScroll = useCallback(() => {
    if (isAutoScrolling) { stopAutoScroll(); return; }
    setIsAutoScrolling(true);
    const scrollStep = () => {
      window.scrollBy({ top: currentScrollSpeed, behavior: "auto" });
      if (window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 10) {
        stopAutoScroll();
        return;
      }
      scrollRef.current = requestAnimationFrame(scrollStep);
    };
    scrollRef.current = requestAnimationFrame(scrollStep);
  }, [isAutoScrolling, currentScrollSpeed, stopAutoScroll]);

  // 4. FILTERED DATA
  const filteredProducts = useMemo(() => {
    let result = filterProducts(products, activeFilters);
    // ... insert your existing sorting logic here (price-asc, etc.)
    return result;
  }, [products, activeFilters, sortBy]);

  return (
    <div className="bg-background min-h-screen text-foreground transition-colors duration-500">
      
      {/* BRAND HERO HEADER */}
      <header className="pt-24 pb-12 border-b border-border px-4">
        <div className="container mx-auto flex flex-col items-center text-center">
          <motion.img 
            initial={{ y: 20, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            src={brandInfo?.logo} 
            alt={brandSlug}
            className="h-16 mb-6 object-contain dark:invert"
          />
          <h1 className="text-4xl md:text-6xl font-black uppercase italic tracking-tighter mb-4">
            {brandSlug} <span className="text-brand">®</span>
          </h1>
          <p className="max-w-xl text-[11px] font-bold uppercase tracking-widest opacity-60 leading-relaxed">
            Premium collection featuring the latest drops and exclusive releases from {brandSlug}. 
            Engineered for performance, designed for the streets.
          </p>
        </div>
      </header>

      {/* MOBILE BAR (Matches your Category UI) */}
      <div className="sticky lg:hidden top-16 z-30 bg-background border-b border-border">
        <div className="flex h-12">
          <button onClick={() => setActiveDrawer("filter")} className="flex-1 flex items-center justify-center gap-2 text-[10px] font-black uppercase border-r border-border">
            <SlidersHorizontal size={13} /> Filter
          </button>
          <button onClick={toggleAutoScroll} className={`flex-1 flex items-center justify-center gap-2 text-[10px] font-black uppercase border-r border-border ${isAutoScrolling ? "text-brand" : ""}`}>
            {isAutoScrolling ? <Square size={12} className="fill-current" /> : <Play size={12} className="fill-current" />}
            Scroll
          </button>
          <button onClick={() => setActiveDrawer("sort")} className="flex-1 flex items-center justify-center gap-2 text-[10px] font-black uppercase">
            <ArrowUpDown size={13} /> Sort
          </button>
        </div>
      </div>

      <main className="container mx-auto flex gap-12 pt-8">
        {/* DESKTOP SIDEBAR (Simplified for Brand page) */}
        <aside className="hidden lg:block w-76 shrink-0 sticky top-26 h-fit pr-6">
          <div className="bg-surface-muted/10 p-6 rounded-[2rem] border border-border">
            <h2 className="text-sm font-black uppercase tracking-widest mb-4 flex items-center gap-2">
              <Info size={16} /> Brand Identity
            </h2>
            <div className="space-y-4 opacity-70 text-[10px] font-bold uppercase leading-5">
              <p>Founded: 1972</p>
              <p>Origin: Beaverton, Oregon</p>
              <p>Focus: Performance / Lifestyle</p>
            </div>
            
            <button 
              onClick={toggleAutoScroll}
              className={`w-full mt-8 py-4 rounded-full border flex items-center justify-center gap-3 transition-all ${
                isAutoScrolling ? "bg-brand text-white border-brand" : "bg-background border-border"
              }`}
            >
              {isAutoScrolling ? <Square size={12} fill="currentColor" /> : <Play size={12} fill="currentColor" />}
              <span className="text-[10px] font-black uppercase tracking-widest">Auto-Scroll</span>
            </button>
          </div>
        </aside>

        {/* PRODUCT GRID */}
        <div className="flex-1 px-4 pb-20">
          <div className="grid grid-cols-2 lg:grid-cols-3 gap-x-4 gap-y-8 sm:gap-x-8">
            <AnimatePresence mode="popLayout">
              {filteredProducts.map((product) => (
                <StoreProductCard key={product.id} product={product} />
              ))}
            </AnimatePresence>
          </div>
        </div>
      </main>

      {/* REUSE MOBILE DRAWER FROM CATEGORY CLIENT HERE */}
      {/* ... (Copy the AnimatePresence Drawer logic from your provided code) */}
    </div>
  );
}